// Déterminer le step de la séquence pour chaque lead
return $input.all().map(item => {
  const lead = item.json;
  let step = 1; // Premier contact par défaut

  if (lead.last_contacted_at) {
    // Vérifier combien de messages ont déjà été envoyés
    // On incrémente le step basé sur next_followup_at
    step = lead.status === 'contacted' ? 2 : 3;
  }

  return {
    json: {
      ...lead,
      current_step: step,
      max_steps: 3 // Premier contact + 2 follow-ups
    }
  };
});

