// Parser la réponse GPT (JSON dans le content)
const lead = $('Déterminer Step Séquence').item.json;
const gptResponse = $input.first().json;

let parsed;
try {
  const content = gptResponse.message?.content || gptResponse.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { subject: 'Question rapide', body: gptResponse.message?.content || 'Erreur de parsing' };
}

// A/B testing : utiliser subject_a ou subject_b aléatoirement
const subject = parsed.subject || (Math.random() > 0.5 ? parsed.subject_a : parsed.subject_b) || 'Question rapide';

return [{
  json: {
    lead_id: lead.id,
    to_email: lead.email,
    to_name: `${lead.first_name} ${lead.last_name}`,
    subject: subject,
    body: parsed.body || '',
    step: lead.current_step,
    ab_variant: parsed.subject_a ? (subject === parsed.subject_a ? 'A' : 'B') : null,
    company_name: lead.company_name
  }
}];

// Throttle : attendre entre chaque email
const delay = parseInt('{{ $env.EMAIL_DELAY_SECONDS }}') || 60;
await new Promise(resolve => setTimeout(resolve, delay * 1000));
return $input.all();
